/**
 * Cross-language zoneKeyID fixtures — hex vectors generated by core/internal/protocol.ZoneKeyID.
 */

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, it } from "node:test";

import { zoneKeyID } from "./alphabet.js";

const fixturesPath = join(
  dirname(fileURLToPath(import.meta.url)),
  "./testdata/zonekey_fixtures.json",
);

describe("zoneKeyID cross-lang fixtures", () => {
  const cases = JSON.parse(readFileSync(fixturesPath, "utf8"));

  for (const tc of cases) {
    it(`${tc.location} × ${tc.collection}`, () => {
      const got = zoneKeyID(tc.collection, tc.location);
      const want = new Uint8Array(Buffer.from(tc.want_hex, "hex"));
      assert.deepEqual(got, want, `zoneKeyID(${tc.collection}, ${tc.location})`);
    });
  }
});
